import{_ as i,o as a,c as o,a2 as t}from"./chunks/framework.YKbyQ3zk.js";const m=JSON.parse('{"title":"Configuration reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/configuration.md","filePath":"reference/configuration.md"}'),s={name:"reference/configuration.md"};function n(r,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[t('<blockquote><p>This file is generated from the configuration definition in <code>@evo-auth/core</code> (<code>packages/core/src/config/definition.ts</code>). Do not edit it by hand: change the source, then run <code>pnpm docs:generate</code> to write it again. <code>pnpm check:docs</code> fails when this file differs from the generated output.</p></blockquote><h1 id="configuration-reference" tabindex="-1">Configuration reference <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to &quot;Configuration reference&quot;">​</a></h1><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Every setting appears once, in the order the definition lists it.</p><h3 id="publicurl" tabindex="-1"><code>publicUrl</code> <a class="header-anchor" href="#publicurl" aria-label="Permalink to &quot;`publicUrl`&quot;">​</a></h3><ul><li>Type: <code>string</code></li><li>Default: none; the setting is required</li><li>Limits: an absolute http or https URL in its normal form (lower-case scheme and host, no default port, no dot segments) with no query, fragment or user name, whose path equals basePath; http needs cookies.devMode; at most 256 characters</li><li>Description: The absolute URL the browser uses for the auth endpoints: the origin plus <code>basePath</code>, for example <code>https://app.example.com/auth</code>. Used exactly as the token issuer (<code>iss</code>), the base of each provider callback (<code>{publicUrl}/{id}/callback</code>) and the JWKS location (<code>{publicUrl}/.well-known/jwks.json</code>), so it must be written exactly as a URL parser would write it back: the origin followed by the path and nothing else.</li></ul><h3 id="basepath" tabindex="-1"><code>basePath</code> <a class="header-anchor" href="#basepath" aria-label="Permalink to &quot;`basePath`&quot;">​</a></h3><ul><li>Type: <code>string</code></li><li>Default: <code>/auth</code></li><li>Limits: one or more /segments of letters, digits and . _ ~ - (the pattern ^(/[A-Za-z0-9._~-]+)+$), with no trailing /, no percent-encoding and no . or .. segment</li><li>Description: The path under which the auth endpoints are served; the refresh cookie&#39;s <code>Path</code>. Only unreserved URL characters are allowed, so the value can be written into the cookie&#39;s <code>Path</code> attribute unchanged and cannot add another attribute such as <code>Domain</code> or <code>SameSite</code>.</li></ul><h3 id="appid" tabindex="-1"><code>appId</code> <a class="header-anchor" href="#appid" aria-label="Permalink to &quot;`appId`&quot;">​</a></h3><ul><li>Type: <code>string</code></li><li>Default: the origin of publicUrl</li><li>Limits: a non-empty string of at most 256 characters with no control characters</li><li>Description: The audience (<code>aud</code>) written into and checked on every access token.</li></ul><h3 id="appname" tabindex="-1"><code>appName</code> <a class="header-anchor" href="#appname" aria-label="Permalink to &quot;`appName`&quot;">​</a></h3><ul><li>Type: <code>string</code></li><li>Default: none (the host name of publicUrl is shown)</li><li>Limits: text of 1 to 64 characters with no control character</li><li>Description: The app&#39;s name as people see it: in the header, heading, subject and button of every email Evo Auth sends, and in the title of the page a sign-in link opens (&quot;Sign in to {appName}&quot;). The browser receives it in <code>publicConfig</code>. While it is unset the host name of <code>publicUrl</code> is shown instead, such as <code>app.example.com</code>.</li></ul><h3 id="cookies" tabindex="-1"><code>cookies</code> <a class="header-anchor" href="#cookies" aria-label="Permalink to &quot;`cookies`&quot;">​</a></h3><h4 id="cookiesprefix" tabindex="-1"><code>cookies.prefix</code> <a class="header-anchor" href="#cookiesprefix" aria-label="Permalink to &quot;`cookies.prefix`&quot;">​</a></h4><ul><li>Type: <code>string</code></li><li>Default: <code>evo</code></li><li>Limits: lower-case letters and digits, at least one</li><li>Description: The prefix of every cookie name, for example <code>__Host-evo_session</code>.</li></ul><h4 id="cookiesdevmode" tabindex="-1"><code>cookies.devMode</code> <a class="header-anchor" href="#cookiesdevmode" aria-label="Permalink to &quot;`cookies.devMode`&quot;">​</a></h4><ul><li>Type: <code>boolean</code></li><li>Default: <code>false</code></li><li>Limits: true only when publicUrl is http on a loopback host (localhost, 127.0.0.0/8 or [::1])</li><li>Description: Development cookie mode: drops the <code>__Host-</code> and <code>__Secure-</code> prefixes and the <code>Secure</code> flag so cookies work on <code>http://localhost</code>. Never for production.</li></ul><h3 id="allowedorigins" tabindex="-1"><code>allowedOrigins</code> <a class="header-anchor" href="#allowedorigins" aria-label="Permalink to &quot;`allowedOrigins`&quot;">​</a></h3><ul><li>Type: <code>string[]</code></li><li>Default: [the origin of publicUrl]</li><li>Limits: exact http or https origins (scheme, host and port only), no wildcards</li><li>Description: Origins whose POST requests are accepted; the CSRF check. Separate from <code>allowedRedirectOrigins</code>.</li></ul><h3 id="allowedredirectorigins" tabindex="-1"><code>allowedRedirectOrigins</code> <a class="header-anchor" href="#allowedredirectorigins" aria-label="Permalink to &quot;`allowedRedirectOrigins`&quot;">​</a></h3><ul><li>Type: <code>string[]</code></li><li>Default: [the origin of publicUrl]</li><li>Limits: exact http or https origins (scheme, host and port only), no wildcards or patterns</li><li>Description: Origins an absolute redirect may point to after sign-in. Any other redirect falls back to <code>afterSignInUrl</code>.</li></ul><h3 id="aftersigninurl" tabindex="-1"><code>afterSignInUrl</code> <a class="header-anchor" href="#aftersigninurl" aria-label="Permalink to &quot;`afterSignInUrl`&quot;">​</a></h3><ul><li>Type: <code>string</code></li><li>Default: <code>/</code></li><li>Limits: a relative path starting with exactly one / (not // or /\\), with no backslash, only visible ASCII characters (U+0021 to U+007E; percent-encode any other character) and no . or .. segment before any ? or #, plain or written with %2e or %2E, or an absolute http or https URL with no user name or password, written exactly as a URL parser writes it back (lower-case scheme and host, the host in its ASCII (xn--) form, no default port, no dot segments, a / before any ? or #, and non-ASCII characters in the path, query and fragment percent-encoded; a bare origin may leave out the final /), whose origin is in allowedRedirectOrigins; no spaces, other whitespace or control characters; at most 2,048 characters</li><li>Description: Where the browser goes after sign-in when no valid redirect was given.</li></ul><h3 id="aftersignouturl" tabindex="-1"><code>afterSignOutUrl</code> <a class="header-anchor" href="#aftersignouturl" aria-label="Permalink to &quot;`afterSignOutUrl`&quot;">​</a></h3><ul><li>Type: <code>string</code></li><li>Default: <code>/</code></li><li>Limits: a relative path starting with exactly one / (not // or /\\), with no backslash, only visible ASCII characters (U+0021 to U+007E; percent-encode any other character) and no . or .. segment before any ? or #, plain or written with %2e or %2E, or an absolute http or https URL with no user name or password, written exactly as a URL parser writes it back (lower-case scheme and host, the host in its ASCII (xn--) form, no default port, no dot segments, a / before any ? or #, and non-ASCII characters in the path, query and fragment percent-encoded; a bare origin may leave out the final /), whose origin is in allowedRedirectOrigins; no spaces, other whitespace or control characters; at most 2,048 characters</li><li>Description: Where the browser goes after sign-out.</li></ul><h3 id="signinurl" tabindex="-1"><code>signInUrl</code> <a class="header-anchor" href="#signinurl" aria-label="Permalink to &quot;`signInUrl`&quot;">​</a></h3><ul><li>Type: <code>string</code></li><li>Default: <code>/sign-in</code></li><li>Limits: a relative path starting with exactly one / (not // or /\\), with no backslash, only visible ASCII characters (U+0021 to U+007E; percent-encode any other character) and no . or .. segment before any ? or #, plain or written with %2e or %2E, or an absolute http or https URL with no user name or password, written exactly as a URL parser writes it back (lower-case scheme and host, the host in its ASCII (xn--) form, no default port, no dot segments, a / before any ? or #, and non-ASCII characters in the path, query and fragment percent-encoded; a bare origin may leave out the final /), whose origin is in allowedRedirectOrigins; no spaces, other whitespace or control characters; at most 2,048 characters</li><li>Description: The app&#39;s sign-in page. Failed navigation requests redirect here with <code>error=&lt;code&gt;</code>.</li></ul><h3 id="session" tabindex="-1"><code>session</code> <a class="header-anchor" href="#session" aria-label="Permalink to &quot;`session`&quot;">​</a></h3><h4 id="sessionlifetimeseconds" tabindex="-1"><code>session.lifetimeSeconds</code> <a class="header-anchor" href="#sessionlifetimeseconds" aria-label="Permalink to &quot;`session.lifetimeSeconds`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: 2592000 (30 days)</li><li>Limits: a whole number from 3600 to 34560000 (1 hour to 400 days, the browsers&#39; cookie limit)</li><li>Description: How long a session lasts from sign-in; the refresh cookie&#39;s lifetime.</li></ul><h3 id="accesstoken" tabindex="-1"><code>accessToken</code> <a class="header-anchor" href="#accesstoken" aria-label="Permalink to &quot;`accessToken`&quot;">​</a></h3><h4 id="accesstokenlifetimeseconds" tabindex="-1"><code>accessToken.lifetimeSeconds</code> <a class="header-anchor" href="#accesstokenlifetimeseconds" aria-label="Permalink to &quot;`accessToken.lifetimeSeconds`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: 300 (5 minutes)</li><li>Limits: a whole number from 60 to 900 (1 to 15 minutes)</li><li>Description: How long an access token (JWT) is valid.</li></ul><h3 id="clockskewseconds" tabindex="-1"><code>clockSkewSeconds</code> <a class="header-anchor" href="#clockskewseconds" aria-label="Permalink to &quot;`clockSkewSeconds`&quot;">​</a></h3><ul><li>Type: <code>integer</code></li><li>Default: <code>5</code></li><li>Limits: a whole number from 0 to 60</li><li>Description: Clock skew allowed when checking a token&#39;s <code>exp</code> and <code>nbf</code>.</li></ul><h3 id="refresh" tabindex="-1"><code>refresh</code> <a class="header-anchor" href="#refresh" aria-label="Permalink to &quot;`refresh`&quot;">​</a></h3><h4 id="refreshreusegraceseconds" tabindex="-1"><code>refresh.reuseGraceSeconds</code> <a class="header-anchor" href="#refreshreusegraceseconds" aria-label="Permalink to &quot;`refresh.reuseGraceSeconds`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>30</code></li><li>Limits: a whole number from 0 to 60</li><li>Description: How long the immediately previous refresh token may be exchanged again, for concurrent reloads and lost responses. 0 turns the window off: then a lost response, a double reload or restored tabs each end the session and cost a sign-in.</li></ul><h3 id="reverification" tabindex="-1"><code>reverification</code> <a class="header-anchor" href="#reverification" aria-label="Permalink to &quot;`reverification`&quot;">​</a></h3><h4 id="reverificationmaxageseconds" tabindex="-1"><code>reverification.maxAgeSeconds</code> <a class="header-anchor" href="#reverificationmaxageseconds" aria-label="Permalink to &quot;`reverification.maxAgeSeconds`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: 600 (10 minutes)</li><li>Limits: a whole number from 60 to 3600 (1 minute to 1 hour)</li><li>Description: How recent the session&#39;s last provider confirmation must be for account deletion.</li></ul><h3 id="ratelimits" tabindex="-1"><code>rateLimits</code> <a class="header-anchor" href="#ratelimits" aria-label="Permalink to &quot;`rateLimits`&quot;">​</a></h3><h4 id="ratelimitsredirect_fallback_sitelimit" tabindex="-1"><code>rateLimits.redirect_fallback_site.limit</code> <a class="header-anchor" href="#ratelimitsredirect_fallback_sitelimit" aria-label="Permalink to &quot;`rateLimits.redirect_fallback_site.limit`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>100</code></li><li>Limits: a whole number from 1 to 1000000</li><li>Description: Requests allowed per window in the <code>redirect_fallback_site</code> bucket. Redirect-fallback warning events across the whole site (key <code>redirect_fallback_site:all</code>). Hit before the per-address bucket; above it the fallback still happens and only the event is skipped.</li></ul><h4 id="ratelimitsredirect_fallback_sitewindowseconds" tabindex="-1"><code>rateLimits.redirect_fallback_site.windowSeconds</code> <a class="header-anchor" href="#ratelimitsredirect_fallback_sitewindowseconds" aria-label="Permalink to &quot;`rateLimits.redirect_fallback_site.windowSeconds`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>600</code></li><li>Limits: a whole number from 1 to 86400 (1 day)</li><li>Description: Length in seconds of the fixed window of the <code>redirect_fallback_site</code> bucket; <code>rateLimits.redirect_fallback_site.limit</code> says what the bucket counts.</li></ul><h4 id="ratelimitsredirect_fallbacklimit" tabindex="-1"><code>rateLimits.redirect_fallback.limit</code> <a class="header-anchor" href="#ratelimitsredirect_fallbacklimit" aria-label="Permalink to &quot;`rateLimits.redirect_fallback.limit`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>1</code></li><li>Limits: a whole number from 1 to 1000000</li><li>Description: Requests allowed per window in the <code>redirect_fallback</code> bucket. Redirect-fallback warning events per client address, counted only when the site-wide bucket admits.</li></ul><h4 id="ratelimitsredirect_fallbackwindowseconds" tabindex="-1"><code>rateLimits.redirect_fallback.windowSeconds</code> <a class="header-anchor" href="#ratelimitsredirect_fallbackwindowseconds" aria-label="Permalink to &quot;`rateLimits.redirect_fallback.windowSeconds`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>600</code></li><li>Limits: a whole number from 1 to 86400 (1 day)</li><li>Description: Length in seconds of the fixed window of the <code>redirect_fallback</code> bucket; <code>rateLimits.redirect_fallback.limit</code> says what the bucket counts.</li></ul><h4 id="ratelimitscallback_refusallimit" tabindex="-1"><code>rateLimits.callback_refusal.limit</code> <a class="header-anchor" href="#ratelimitscallback_refusallimit" aria-label="Permalink to &quot;`rateLimits.callback_refusal.limit`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>20</code></li><li>Limits: a whole number from 1 to 1000000</li><li>Description: Requests allowed per window in the <code>callback_refusal</code> bucket. Refused sign-in callbacks per client address, counted only when the request is refused after the sign-in cookie opened, so successful sign-ins never count.</li></ul><h4 id="ratelimitscallback_refusalwindowseconds" tabindex="-1"><code>rateLimits.callback_refusal.windowSeconds</code> <a class="header-anchor" href="#ratelimitscallback_refusalwindowseconds" aria-label="Permalink to &quot;`rateLimits.callback_refusal.windowSeconds`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>600</code></li><li>Limits: a whole number from 1 to 86400 (1 day)</li><li>Description: Length in seconds of the fixed window of the <code>callback_refusal</code> bucket; <code>rateLimits.callback_refusal.limit</code> says what the bucket counts.</li></ul><h4 id="ratelimitssign_in_accountlimit" tabindex="-1"><code>rateLimits.sign_in_account.limit</code> <a class="header-anchor" href="#ratelimitssign_in_accountlimit" aria-label="Permalink to &quot;`rateLimits.sign_in_account.limit`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>10</code></li><li>Limits: a whole number from 1 to 1000000</li><li>Description: Requests allowed per window in the <code>sign_in_account</code> bucket. Successful sign-ins per provider account, counted once the account is known.</li></ul><h4 id="ratelimitssign_in_accountwindowseconds" tabindex="-1"><code>rateLimits.sign_in_account.windowSeconds</code> <a class="header-anchor" href="#ratelimitssign_in_accountwindowseconds" aria-label="Permalink to &quot;`rateLimits.sign_in_account.windowSeconds`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>600</code></li><li>Limits: a whole number from 1 to 86400 (1 day)</li><li>Description: Length in seconds of the fixed window of the <code>sign_in_account</code> bucket; <code>rateLimits.sign_in_account.limit</code> says what the bucket counts.</li></ul><h4 id="ratelimitssession_refreshlimit" tabindex="-1"><code>rateLimits.session_refresh.limit</code> <a class="header-anchor" href="#ratelimitssession_refreshlimit" aria-label="Permalink to &quot;`rateLimits.session_refresh.limit`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>60</code></li><li>Limits: a whole number from 1 to 1000000</li><li>Description: Requests allowed per window in the <code>session_refresh</code> bucket. Refresh-token exchanges per session at the handshake and <code>POST {basePath}/token</code>, counted after reuse is checked, so a tripped limit never hides a reuse.</li></ul><h4 id="ratelimitssession_refreshwindowseconds" tabindex="-1"><code>rateLimits.session_refresh.windowSeconds</code> <a class="header-anchor" href="#ratelimitssession_refreshwindowseconds" aria-label="Permalink to &quot;`rateLimits.session_refresh.windowSeconds`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>600</code></li><li>Limits: a whole number from 1 to 86400 (1 day)</li><li>Description: Length in seconds of the fixed window of the <code>session_refresh</code> bucket; <code>rateLimits.session_refresh.limit</code> says what the bucket counts.</li></ul><h4 id="ratelimitsself_readlimit" tabindex="-1"><code>rateLimits.self_read.limit</code> <a class="header-anchor" href="#ratelimitsself_readlimit" aria-label="Permalink to &quot;`rateLimits.self_read.limit`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>300</code></li><li>Limits: a whole number from 1 to 1000000</li><li>Description: Requests allowed per window in the <code>self_read</code> bucket. <code>GET {basePath}/me</code> and <code>GET {basePath}/sessions</code> carrying a Bearer token, per client address.</li></ul><h4 id="ratelimitsself_readwindowseconds" tabindex="-1"><code>rateLimits.self_read.windowSeconds</code> <a class="header-anchor" href="#ratelimitsself_readwindowseconds" aria-label="Permalink to &quot;`rateLimits.self_read.windowSeconds`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>600</code></li><li>Limits: a whole number from 1 to 86400 (1 day)</li><li>Description: Length in seconds of the fixed window of the <code>self_read</code> bucket; <code>rateLimits.self_read.limit</code> says what the bucket counts.</li></ul><h4 id="ratelimitsself_servicelimit" tabindex="-1"><code>rateLimits.self_service.limit</code> <a class="header-anchor" href="#ratelimitsself_servicelimit" aria-label="Permalink to &quot;`rateLimits.self_service.limit`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>30</code></li><li>Limits: a whole number from 1 to 1000000</li><li>Description: Requests allowed per window in the <code>self_service</code> bucket. Self-service POSTs (session revoke, sign out everywhere, account delete) per session.</li></ul><h4 id="ratelimitsself_servicewindowseconds" tabindex="-1"><code>rateLimits.self_service.windowSeconds</code> <a class="header-anchor" href="#ratelimitsself_servicewindowseconds" aria-label="Permalink to &quot;`rateLimits.self_service.windowSeconds`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>600</code></li><li>Limits: a whole number from 1 to 86400 (1 day)</li><li>Description: Length in seconds of the fixed window of the <code>self_service</code> bucket; <code>rateLimits.self_service.limit</code> says what the bucket counts.</li></ul><h4 id="ratelimitsadmin_readlimit" tabindex="-1"><code>rateLimits.admin_read.limit</code> <a class="header-anchor" href="#ratelimitsadmin_readlimit" aria-label="Permalink to &quot;`rateLimits.admin_read.limit`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>300</code></li><li>Limits: a whole number from 1 to 1000000</li><li>Description: Requests allowed per window in the <code>admin_read</code> bucket. Admin GET routes under <code>{basePath}/admin/</code> per session, counted once the caller has passed the admin check.</li></ul><h4 id="ratelimitsadmin_readwindowseconds" tabindex="-1"><code>rateLimits.admin_read.windowSeconds</code> <a class="header-anchor" href="#ratelimitsadmin_readwindowseconds" aria-label="Permalink to &quot;`rateLimits.admin_read.windowSeconds`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>600</code></li><li>Limits: a whole number from 1 to 86400 (1 day)</li><li>Description: Length in seconds of the fixed window of the <code>admin_read</code> bucket; <code>rateLimits.admin_read.limit</code> says what the bucket counts.</li></ul><h4 id="ratelimitsadmin_writelimit" tabindex="-1"><code>rateLimits.admin_write.limit</code> <a class="header-anchor" href="#ratelimitsadmin_writelimit" aria-label="Permalink to &quot;`rateLimits.admin_write.limit`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>30</code></li><li>Limits: a whole number from 1 to 1000000</li><li>Description: Requests allowed per window in the <code>admin_write</code> bucket. Admin POST routes under <code>{basePath}/admin/</code> (ban, unban, delete, session revoke, revoke all) per session, counted once the caller has passed the admin check.</li></ul><h4 id="ratelimitsadmin_writewindowseconds" tabindex="-1"><code>rateLimits.admin_write.windowSeconds</code> <a class="header-anchor" href="#ratelimitsadmin_writewindowseconds" aria-label="Permalink to &quot;`rateLimits.admin_write.windowSeconds`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>600</code></li><li>Limits: a whole number from 1 to 86400 (1 day)</li><li>Description: Length in seconds of the fixed window of the <code>admin_write</code> bucket; <code>rateLimits.admin_write.limit</code> says what the bucket counts.</li></ul><h4 id="ratelimitsauthorizelimit" tabindex="-1"><code>rateLimits.authorize.limit</code> <a class="header-anchor" href="#ratelimitsauthorizelimit" aria-label="Permalink to &quot;`rateLimits.authorize.limit`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>20</code></li><li>Limits: a whole number from 1 to 1000000</li><li>Description: Requests allowed per window in the <code>authorize</code> bucket. Refused requests to the hub&#39;s <code>GET {basePath}/oidc/authorize</code> per client address, in hub mode only. Only a refusal counts, so a sign-in through the hub never does.</li></ul><h4 id="ratelimitsauthorizewindowseconds" tabindex="-1"><code>rateLimits.authorize.windowSeconds</code> <a class="header-anchor" href="#ratelimitsauthorizewindowseconds" aria-label="Permalink to &quot;`rateLimits.authorize.windowSeconds`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>600</code></li><li>Limits: a whole number from 1 to 86400 (1 day)</li><li>Description: Length in seconds of the fixed window of the <code>authorize</code> bucket; <code>rateLimits.authorize.limit</code> says what the bucket counts.</li></ul><h4 id="ratelimitstokenlimit" tabindex="-1"><code>rateLimits.token.limit</code> <a class="header-anchor" href="#ratelimitstokenlimit" aria-label="Permalink to &quot;`rateLimits.token.limit`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>20</code></li><li>Limits: a whole number from 1 to 1000000</li><li>Description: Requests allowed per window in the <code>token</code> bucket. Refused requests to the hub&#39;s <code>POST {basePath}/oidc/token</code> per client (the app&#39;s origin) and client address, in hub mode only; a request whose client the allowed-sites rule refuses counts per client address alone. Only a refusal counts, so a code exchanged correctly never does.</li></ul><h4 id="ratelimitstokenwindowseconds" tabindex="-1"><code>rateLimits.token.windowSeconds</code> <a class="header-anchor" href="#ratelimitstokenwindowseconds" aria-label="Permalink to &quot;`rateLimits.token.windowSeconds`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>600</code></li><li>Limits: a whole number from 1 to 86400 (1 day)</li><li>Description: Length in seconds of the fixed window of the <code>token</code> bucket; <code>rateLimits.token.limit</code> says what the bucket counts.</li></ul><h4 id="ratelimitspasskey_signinlimit" tabindex="-1"><code>rateLimits.passkey_signin.limit</code> <a class="header-anchor" href="#ratelimitspasskey_signinlimit" aria-label="Permalink to &quot;`rateLimits.passkey_signin.limit`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>20</code></li><li>Limits: a whole number from 1 to 1000000</li><li>Description: Requests allowed per window in the <code>passkey_signin</code> bucket. Passkey sign-in completions (<code>POST {basePath}/passkeys/signin/verify</code>) per client address, each one counted before the passkey is checked, so a run of guesses from one address is stopped; only while <code>passkeys.enabled</code> is true.</li></ul><h4 id="ratelimitspasskey_signinwindowseconds" tabindex="-1"><code>rateLimits.passkey_signin.windowSeconds</code> <a class="header-anchor" href="#ratelimitspasskey_signinwindowseconds" aria-label="Permalink to &quot;`rateLimits.passkey_signin.windowSeconds`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>600</code></li><li>Limits: a whole number from 1 to 86400 (1 day)</li><li>Description: Length in seconds of the fixed window of the <code>passkey_signin</code> bucket; <code>rateLimits.passkey_signin.limit</code> says what the bucket counts.</li></ul><h4 id="ratelimitsorganization_createlimit" tabindex="-1"><code>rateLimits.organization_create.limit</code> <a class="header-anchor" href="#ratelimitsorganization_createlimit" aria-label="Permalink to &quot;`rateLimits.organization_create.limit`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>10</code></li><li>Limits: a whole number from 1 to 1000000</li><li>Description: Requests allowed per window in the <code>organization_create</code> bucket. Organisations a signed-in user creates, per user, counted once a creation succeeds. The server API&#39;s creations are not counted.</li></ul><h4 id="ratelimitsorganization_createwindowseconds" tabindex="-1"><code>rateLimits.organization_create.windowSeconds</code> <a class="header-anchor" href="#ratelimitsorganization_createwindowseconds" aria-label="Permalink to &quot;`rateLimits.organization_create.windowSeconds`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>600</code></li><li>Limits: a whole number from 1 to 86400 (1 day)</li><li>Description: Length in seconds of the fixed window of the <code>organization_create</code> bucket; <code>rateLimits.organization_create.limit</code> says what the bucket counts.</li></ul><h4 id="ratelimitsemail_sendlimit" tabindex="-1"><code>rateLimits.email_send.limit</code> <a class="header-anchor" href="#ratelimitsemail_sendlimit" aria-label="Permalink to &quot;`rateLimits.email_send.limit`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>10</code></li><li>Limits: a whole number from 1 to 1000000</li><li>Description: Requests allowed per window in the <code>email_send</code> bucket. Emails asked for per client address: each <code>POST {basePath}/email/sign-in/code</code> and each invitation sent to an address, counted before anything is written or sent; only while an email setting is on.</li></ul><h4 id="ratelimitsemail_sendwindowseconds" tabindex="-1"><code>rateLimits.email_send.windowSeconds</code> <a class="header-anchor" href="#ratelimitsemail_sendwindowseconds" aria-label="Permalink to &quot;`rateLimits.email_send.windowSeconds`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>3600</code></li><li>Limits: a whole number from 1 to 86400 (1 day)</li><li>Description: Length in seconds of the fixed window of the <code>email_send</code> bucket; <code>rateLimits.email_send.limit</code> says what the bucket counts.</li></ul><h4 id="ratelimitsemail_recipientlimit" tabindex="-1"><code>rateLimits.email_recipient.limit</code> <a class="header-anchor" href="#ratelimitsemail_recipientlimit" aria-label="Permalink to &quot;`rateLimits.email_recipient.limit`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>5</code></li><li>Limits: a whole number from 1 to 1000000</li><li>Description: Requests allowed per window in the <code>email_recipient</code> bucket. Emails asked for per recipient (the normalised address, kept only as a hash), whichever client asks, counted with <code>email_send</code>, so no one can flood an inbox through the app.</li></ul><h4 id="ratelimitsemail_recipientwindowseconds" tabindex="-1"><code>rateLimits.email_recipient.windowSeconds</code> <a class="header-anchor" href="#ratelimitsemail_recipientwindowseconds" aria-label="Permalink to &quot;`rateLimits.email_recipient.windowSeconds`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>3600</code></li><li>Limits: a whole number from 1 to 86400 (1 day)</li><li>Description: Length in seconds of the fixed window of the <code>email_recipient</code> bucket; <code>rateLimits.email_recipient.limit</code> says what the bucket counts.</li></ul><h4 id="ratelimitspassword_sign_in_accountlimit" tabindex="-1"><code>rateLimits.password_sign_in_account.limit</code> <a class="header-anchor" href="#ratelimitspassword_sign_in_accountlimit" aria-label="Permalink to &quot;`rateLimits.password_sign_in_account.limit`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>10</code></li><li>Limits: a whole number from 1 to 1000000</li><li>Description: Requests allowed per window in the <code>password_sign_in_account</code> bucket. Failed password sign-ins per identifier typed, whichever client tries: per address at <code>POST {basePath}/email/sign-in/password</code>, and per username at <code>POST {basePath}/username/sign-in</code> while <code>usernames.enabled</code> is true, each kept only as a hash, so a full bucket for a username never changes the answers for the account&#39;s address, or the reverse; the 100 failures in a row that turn a password off are counted on the password whichever way in. Only failures count, so signing in never does. Only while <code>emailAuth.password</code> is true.</li></ul><h4 id="ratelimitspassword_sign_in_accountwindowseconds" tabindex="-1"><code>rateLimits.password_sign_in_account.windowSeconds</code> <a class="header-anchor" href="#ratelimitspassword_sign_in_accountwindowseconds" aria-label="Permalink to &quot;`rateLimits.password_sign_in_account.windowSeconds`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>900</code></li><li>Limits: a whole number from 1 to 86400 (1 day)</li><li>Description: Length in seconds of the fixed window of the <code>password_sign_in_account</code> bucket; <code>rateLimits.password_sign_in_account.limit</code> says what the bucket counts.</li></ul><h4 id="ratelimitspassword_sign_in_addresslimit" tabindex="-1"><code>rateLimits.password_sign_in_address.limit</code> <a class="header-anchor" href="#ratelimitspassword_sign_in_addresslimit" aria-label="Permalink to &quot;`rateLimits.password_sign_in_address.limit`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>30</code></li><li>Limits: a whole number from 1 to 1000000</li><li>Description: Requests allowed per window in the <code>password_sign_in_address</code> bucket. Failed password sign-ins per client address, across every address tried; only failures count. Only while <code>emailAuth.password</code> is true.</li></ul><h4 id="ratelimitspassword_sign_in_addresswindowseconds" tabindex="-1"><code>rateLimits.password_sign_in_address.windowSeconds</code> <a class="header-anchor" href="#ratelimitspassword_sign_in_addresswindowseconds" aria-label="Permalink to &quot;`rateLimits.password_sign_in_address.windowSeconds`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>900</code></li><li>Limits: a whole number from 1 to 86400 (1 day)</li><li>Description: Length in seconds of the fixed window of the <code>password_sign_in_address</code> bucket; <code>rateLimits.password_sign_in_address.limit</code> says what the bucket counts.</li></ul><h4 id="ratelimitsemail_sign_uplimit" tabindex="-1"><code>rateLimits.email_sign_up.limit</code> <a class="header-anchor" href="#ratelimitsemail_sign_uplimit" aria-label="Permalink to &quot;`rateLimits.email_sign_up.limit`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>10</code></li><li>Limits: a whole number from 1 to 1000000</li><li>Description: Requests allowed per window in the <code>email_sign_up</code> bucket. Sign-ups per client address: password sign-ups (<code>POST {basePath}/email/sign-up</code>) and passkey sign-ups (<code>POST {basePath}/passkeys/sign-up/start</code>), counted before anything is written or sent. Only while <code>emailAuth.password</code> and <code>emailAuth.signUp</code> are both true, or <code>passkeys.signUp</code> is true.</li></ul><h4 id="ratelimitsemail_sign_upwindowseconds" tabindex="-1"><code>rateLimits.email_sign_up.windowSeconds</code> <a class="header-anchor" href="#ratelimitsemail_sign_upwindowseconds" aria-label="Permalink to &quot;`rateLimits.email_sign_up.windowSeconds`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>3600</code></li><li>Limits: a whole number from 1 to 86400 (1 day)</li><li>Description: Length in seconds of the fixed window of the <code>email_sign_up</code> bucket; <code>rateLimits.email_sign_up.limit</code> says what the bucket counts.</li></ul><h4 id="ratelimitssecond_factor_userlimit" tabindex="-1"><code>rateLimits.second_factor_user.limit</code> <a class="header-anchor" href="#ratelimitssecond_factor_userlimit" aria-label="Permalink to &quot;`rateLimits.second_factor_user.limit`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>10</code></li><li>Limits: a whole number from 1 to 1000000</li><li>Description: Requests allowed per window in the <code>second_factor_user</code> bucket. Wrong second-step codes per user, across sign-in steps: authenticator codes, backup codes and refused passkey responses at the second step, and wrong codes that confirm identity for a user with a second factor. Only failures count; while it is full a right code is refused too. Only while <code>secondFactor.enabled</code> is true.</li></ul><h4 id="ratelimitssecond_factor_userwindowseconds" tabindex="-1"><code>rateLimits.second_factor_user.windowSeconds</code> <a class="header-anchor" href="#ratelimitssecond_factor_userwindowseconds" aria-label="Permalink to &quot;`rateLimits.second_factor_user.windowSeconds`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>900</code></li><li>Limits: a whole number from 1 to 86400 (1 day)</li><li>Description: Length in seconds of the fixed window of the <code>second_factor_user</code> bucket; <code>rateLimits.second_factor_user.limit</code> says what the bucket counts.</li></ul><h4 id="ratelimitsusername_changelimit" tabindex="-1"><code>rateLimits.username_change.limit</code> <a class="header-anchor" href="#ratelimitsusername_changelimit" aria-label="Permalink to &quot;`rateLimits.username_change.limit`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>10</code></li><li>Limits: a whole number from 1 to 1000000</li><li>Description: Requests allowed per window in the <code>username_change</code> bucket. Username changes per user (<code>POST {basePath}/account/username</code>): every attempt counts, refused ones included, so a signed-in person can try at most 10 names a day. Only while <code>usernames.enabled</code> is true.</li></ul><h4 id="ratelimitsusername_changewindowseconds" tabindex="-1"><code>rateLimits.username_change.windowSeconds</code> <a class="header-anchor" href="#ratelimitsusername_changewindowseconds" aria-label="Permalink to &quot;`rateLimits.username_change.windowSeconds`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>86400</code></li><li>Limits: a whole number from 1 to 86400 (1 day)</li><li>Description: Length in seconds of the fixed window of the <code>username_change</code> bucket; <code>rateLimits.username_change.limit</code> says what the bucket counts.</li></ul><h4 id="ratelimitssecond_factor_addresslimit" tabindex="-1"><code>rateLimits.second_factor_address.limit</code> <a class="header-anchor" href="#ratelimitssecond_factor_addresslimit" aria-label="Permalink to &quot;`rateLimits.second_factor_address.limit`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>30</code></li><li>Limits: a whole number from 1 to 1000000</li><li>Description: Requests allowed per window in the <code>second_factor_address</code> bucket. Wrong second-step codes per client address, across every user tried; only failures count. Only while <code>secondFactor.enabled</code> is true.</li></ul><h4 id="ratelimitssecond_factor_addresswindowseconds" tabindex="-1"><code>rateLimits.second_factor_address.windowSeconds</code> <a class="header-anchor" href="#ratelimitssecond_factor_addresswindowseconds" aria-label="Permalink to &quot;`rateLimits.second_factor_address.windowSeconds`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>900</code></li><li>Limits: a whole number from 1 to 86400 (1 day)</li><li>Description: Length in seconds of the fixed window of the <code>second_factor_address</code> bucket; <code>rateLimits.second_factor_address.limit</code> says what the bucket counts.</li></ul><h3 id="authevents" tabindex="-1"><code>authEvents</code> <a class="header-anchor" href="#authevents" aria-label="Permalink to &quot;`authEvents`&quot;">​</a></h3><h4 id="autheventsretentionseconds" tabindex="-1"><code>authEvents.retentionSeconds</code> <a class="header-anchor" href="#autheventsretentionseconds" aria-label="Permalink to &quot;`authEvents.retentionSeconds`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: 7776000 (90 days)</li><li>Limits: a whole number from 86400 to 34560000 (1 to 400 days)</li><li>Description: How long an auth event row is kept: each row&#39;s <code>expiresAt</code> is set when it is written, to its time plus this value, and a batched sweep removes expired rows. Changing the setting rewrites neither the auth event rows already written nor the <code>purgeAt</code> of session rows already written; they keep the values set when they were written.</li></ul><h3 id="admins" tabindex="-1"><code>admins</code> <a class="header-anchor" href="#admins" aria-label="Permalink to &quot;`admins`&quot;">​</a></h3><h4 id="adminsuserids" tabindex="-1"><code>admins.userIds</code> <a class="header-anchor" href="#adminsuserids" aria-label="Permalink to &quot;`admins.userIds`&quot;">​</a></h4><ul><li>Type: <code>string[]</code></li><li>Default: [] (no admins: every admin route answers 404)</li><li>Limits: a list of user ids, each of 1 to 64 printable ASCII characters (U+0021 to U+007E)</li><li>Description: The user ids of the admins, checked on the server on every request to the admin routes under <code>{basePath}/admin/</code>. With the list empty those routes do not exist and answer 404 for every method; a user whose id is not listed gets the same 404. Admin status is never read from a token, and the list never reaches the browser. Changing it needs a deploy. A signed-in user can read their own id as <code>user.id</code> in the answer of <code>GET {basePath}/me</code>.</li></ul><h3 id="hub" tabindex="-1"><code>hub</code> <a class="header-anchor" href="#hub" aria-label="Permalink to &quot;`hub`&quot;">​</a></h3><h4 id="hubenabled" tabindex="-1"><code>hub.enabled</code> <a class="header-anchor" href="#hubenabled" aria-label="Permalink to &quot;`hub.enabled`&quot;">​</a></h4><ul><li>Type: <code>boolean</code></li><li>Default: <code>false</code></li><li>Limits: true or false; true needs an appId that is not a URL origin, such as my-hub, and a publicUrl whose host does not end in a dot</li><li>Description: Hub mode: this deployment also becomes a small OpenID provider that other Evo Auth apps sign in through, so each sign-in provider is set up once. Off by default, and with it off nothing changes. With it on, <code>appId</code> must be set to a name that is not a URL origin, so the hub&#39;s own access tokens and the id_tokens it gives apps never share an audience, and the host of <code>publicUrl</code> must not end in a dot, so the hub&#39;s own origin has one spelling. With more than one provider in <code>providers</code>, a person signing in at the hub picks one on the hub&#39;s sign-in page. It adds the routes <code>GET {basePath}/oidc/authorize</code>, <code>POST {basePath}/oidc/token</code> and <code>GET {basePath}/.well-known/openid-configuration</code>.</li></ul><h4 id="huballowedclients" tabindex="-1"><code>hub.allowedClients</code> <a class="header-anchor" href="#huballowedclients" aria-label="Permalink to &quot;`hub.allowedClients`&quot;">​</a></h4><ul><li>Type: <code>string[]</code></li><li>Default: [] (no site may use the hub)</li><li>Limits: a list of entries, each an exact callback address written as a URL parser writes it back, with a path other than / and no query, fragment, user information or dot at the end of the host: on an https origin or an http origin on localhost or 127.0.0.1; https://*.&lt;parent&gt;/&lt;path&gt; where &lt;parent&gt; is the host of publicUrl without its first label, publicUrl is https and &lt;parent&gt; has two labels or more, and the star stands for exactly one label (no port); or <a href="http://localhost/%5C" target="_blank" rel="noreferrer">http://localhost/\\</a>&lt;path&gt; or <a href="http://127.0.0.1/%5C" target="_blank" rel="noreferrer">http://127.0.0.1/\\</a>&lt;path&gt;, which match that host on any port. An origin alone is refused</li><li>Description: The sites that may sign in through the hub, by the exact callback address the hub sends each one&#39;s code to. An app&#39;s client id is its own origin and it has no secret; its entry here is its callback address, <code>{publicUrl}/{provider id}/callback</code>, such as <code>https://notes.example.com/auth/evo/callback</code> for an app using <code>evoHub()</code> with its default id, which <code>evo-auth check</code> on the app prints. The hub accepts a sign-in request only from a client an entry matches, sends its code only to that entry&#39;s address exactly (no other path, no added query, no trailing slash), and never accepts its own origin, whatever the list says. A wildcard may cover only the hub&#39;s own parent domain: for a hub at <code>https://auth.example.com</code>, <code>https://*.example.com/auth/evo/callback</code> is accepted and matches <code>https://notes.example.com/auth/evo/callback</code>, and every other site is listed exactly. Use a wildcard only for a domain you own: on a shared hosting name, such as a hub at <code>https://my-hub.vercel.app</code> listing <code>https://*.vercel.app</code>, it lets every app anyone hosts there sign in through the hub, and <code>evo-auth check</code> warns about every wildcard. Empty by default, which refuses every site: without the list any site could use the hub&#39;s provider apps to sign people in and receive their identity. Read only when <code>hub.enabled</code> is true.</li></ul><h3 id="passkeys" tabindex="-1"><code>passkeys</code> <a class="header-anchor" href="#passkeys" aria-label="Permalink to &quot;`passkeys`&quot;">​</a></h3><h4 id="passkeysenabled" tabindex="-1"><code>passkeys.enabled</code> <a class="header-anchor" href="#passkeysenabled" aria-label="Permalink to &quot;`passkeys.enabled`&quot;">​</a></h4><ul><li>Type: <code>boolean</code></li><li>Default: <code>false</code></li><li>Limits: true or false</li><li>Description: Passkeys: a signed-in user can add a passkey (WebAuthn) from their profile, then sign in or confirm their identity with it. Off by default, and with it off nothing changes. A passkey is added to an existing account after a recent confirmation, like linking a provider account, unless <code>passkeys.signUp</code> is on, when a new person can also sign up with an email address and a passkey. A user&#39;s accounts and passkeys count together as their ways to sign in, so the last one cannot be removed, by the user or by an admin.</li></ul><h4 id="passkeyssignup" tabindex="-1"><code>passkeys.signUp</code> <a class="header-anchor" href="#passkeyssignup" aria-label="Permalink to &quot;`passkeys.signUp`&quot;">​</a></h4><ul><li>Type: <code>boolean</code></li><li>Default: <code>false</code></li><li>Limits: true or false</li><li>Description: Passkey sign-up: a new person can sign up with an email address and a passkey, and never sets a password. The address is proved first by an emailed code, or a link while <code>emailAuth.link</code> is on, and the account is created only in the step that stores the passkey, so a half-finished sign-up leaves no account behind. Adds <code>POST {basePath}/passkeys/sign-up/start</code>, <code>/passkeys/sign-up/options</code> and <code>/passkeys/sign-up/verify</code>. Needs <code>passkeys.enabled</code>, <code>emailAuth.signUp</code> (so one switch still stops every kind of sign-up), <code>email.sender</code>, and at least one of <code>emailAuth.code</code>, <code>emailAuth.link</code> and <code>emailAuth.password</code>, so a person who signed up this way has a way back by email if the passkey is lost. Off by default.</li></ul><h4 id="passkeysrpid" tabindex="-1"><code>passkeys.rpId</code> <a class="header-anchor" href="#passkeysrpid" aria-label="Permalink to &quot;`passkeys.rpId`&quot;">​</a></h4><ul><li>Type: <code>string</code></li><li>Default: the host name of publicUrl</li><li>Limits: a lower-case host name that equals the host name of publicUrl or is a parent domain of it (a suffix after a dot) with at least two labels; a parent domain only when the host of publicUrl is a name, not an IP address; at most 253 characters</li><li>Description: The relying party id passkeys are bound to. The browser lets a passkey be used only on this host name and the ones under it, so set it to a parent domain, such as <code>example.com</code> for a <code>publicUrl</code> at <code>https://auth.example.com/auth</code>, only when passkeys made here must also work on its other subdomains. Changing it later makes every passkey already added unusable. Checked at start-up whenever it is set, and used only when <code>passkeys.enabled</code> is true.</li></ul><h3 id="organizations" tabindex="-1"><code>organizations</code> <a class="header-anchor" href="#organizations" aria-label="Permalink to &quot;`organizations`&quot;">​</a></h3><h4 id="organizationsenabled" tabindex="-1"><code>organizations.enabled</code> <a class="header-anchor" href="#organizationsenabled" aria-label="Permalink to &quot;`organizations.enabled`&quot;">​</a></h4><ul><li>Type: <code>boolean</code></li><li>Default: <code>false</code></li><li>Limits: true or false; true needs organizations.invitationUrl</li><li>Description: Organisations: groups of the app&#39;s users, each member with a role from <code>organizations.roles</code>. Off by default, and with it off nothing changes. Every organisation keeps at least one member whose role holds <code>org:memberships:manage</code>, so a change of role, a removal or a leaving that would leave none is refused, whoever asks.</li></ul><h4 id="organizationsroles" tabindex="-1"><code>organizations.roles</code> <a class="header-anchor" href="#organizationsroles" aria-label="Permalink to &quot;`organizations.roles`&quot;">​</a></h4><ul><li>Type: <code>Record&lt;string, Role&gt;</code></li><li>Default: { admin: { label: &quot;Admin&quot;, permissions: the five system permissions }, member: { label: &quot;Member&quot;, permissions: [&quot;org:memberships:read&quot;] } }</li><li>Limits: an object mapping each role key (a lower-case letter, then lower-case letters, digits, - and _, at most 32 characters) to { label, permissions }: a label of 1 to 64 characters with no control character, and a list of at most 32 different permissions, each one of the five system permissions (org:profile:manage, org:profile:delete, org:memberships:read, org:memberships:manage, org:invitations:manage) or an app permission feature:action in lower-case letters, digits, - and _, each part starting with a letter, neither part org, at most 48 characters; at least one role</li><li>Description: The roles a member of an organisation can have and what each may do. Core checks the five system permissions; an app checks its own <code>feature:action</code> permissions. Roles live here, not in the database, so a change takes effect at the next deploy: a membership whose role is no longer listed holds no permissions until it is given another, and <code>evo-auth-server check</code> reports such memberships. Both <code>evo-auth check</code> and <code>evo-auth-server check</code> print a fingerprint of the roles, so two configs, such as the issuer&#39;s and a verifier&#39;s, can be compared by it. While organisations are on, each role&#39;s key and label reach the browser in <code>publicConfig</code>, so labels are public: a signed-out visitor can see them. Permissions are never sent there.</li></ul><h4 id="organizationscreatorrole" tabindex="-1"><code>organizations.creatorRole</code> <a class="header-anchor" href="#organizationscreatorrole" aria-label="Permalink to &quot;`organizations.creatorRole`&quot;">​</a></h4><ul><li>Type: <code>string</code></li><li>Default: <code>admin</code></li><li>Limits: a key of organizations.roles whose role holds org:memberships:manage</li><li>Description: The role the user who creates an organisation is given. It must hold <code>org:memberships:manage</code>, so every organisation starts with a member who can manage its members.</li></ul><h4 id="organizationscreation" tabindex="-1"><code>organizations.creation</code> <a class="header-anchor" href="#organizationscreation" aria-label="Permalink to &quot;`organizations.creation`&quot;">​</a></h4><ul><li>Type: <code>string</code></li><li>Default: <code>anyone</code></li><li>Limits: anyone or admins</li><li>Description: Who may create an organisation: <code>anyone</code> signed in, or <code>admins</code>, the users in <code>admins.userIds</code>. The server API may create one for any user either way. Creations are counted per user in the <code>organization_create</code> rate-limit bucket.</li></ul><h4 id="organizationsinvitationurl" tabindex="-1"><code>organizations.invitationUrl</code> <a class="header-anchor" href="#organizationsinvitationurl" aria-label="Permalink to &quot;`organizations.invitationUrl`&quot;">​</a></h4><ul><li>Type: <code>string</code></li><li>Default: none (required while organizations.enabled is true)</li><li>Limits: a relative path starting with exactly one / (not // or /\\), with no backslash, only visible ASCII characters (U+0021 to U+007E; percent-encode any other character) and no . or .. segment before any ? or #, plain or written with %2e or %2E, or an absolute http or https URL with no user name or password, written exactly as a URL parser writes it back (lower-case scheme and host, the host in its ASCII (xn--) form, no default port, no dot segments, a / before any ? or #, and non-ASCII characters in the path, query and fragment percent-encoded; a bare origin may leave out the final /), whose origin is in allowedRedirectOrigins; no spaces, other whitespace or control characters; at most 2,048 characters</li><li>Description: The page of the app where a person opens an invitation link to join an organisation: an invitation&#39;s link is this address with the invitation token added. Required while <code>organizations.enabled</code> is true.</li></ul><h3 id="email" tabindex="-1"><code>email</code> <a class="header-anchor" href="#email" aria-label="Permalink to &quot;`email`&quot;">​</a></h3><h4 id="emailsender" tabindex="-1"><code>email.sender</code> <a class="header-anchor" href="#emailsender" aria-label="Permalink to &quot;`email.sender`&quot;">​</a></h4><ul><li>Type: <code>EmailSender</code></li><li>Default: none (no email is sent)</li><li>Limits: a function (message, { signal, deadline }) =&gt; Promise&lt;void&gt;, or on Convex a reference to one of the app&#39;s actions, such as internal.email.send; required while any emailAuth setting is true</li><li>Description: Sends the email Evo Auth writes: sign-in codes and links, the codes of sign-up, password reset and adding an address, the note to an address that already has an account, and invitations sent to an address. Core never sends mail itself and holds no mail account or key: the sender keeps those in its own closure. On Convex give a reference to one of the app&#39;s actions, which is run with <code>ctx.runAction</code> and passed the message as its arguments. A code or link is sent by the email job after the route that asks for it, such as <code>POST {basePath}/email/sign-in/code</code>, has answered, never during the request, so how long the answer takes cannot tell which addresses have accounts: the job decides whether the address gets a message, saves the hashes of what it sends, then calls the sender. On the Node server the job runs in the server&#39;s job runner; on Convex it is the app&#39;s own action, set up with two lines: <code>export const emailJob = createEmailJob(components.evoauth, { config })</code> in a file such as <code>convex/auth.ts</code>, and <code>registerRoutes(http, components.evoauth, { config, emailJob: internal.auth.emailJob })</code>. An invitation sent to an address is sent in the request, after the invitation is saved. An error the sender throws is logged as <code>email.send_failed</code> and is not retried, and the answer to the request does not change. A send is waited for at most 30 seconds: then the <code>signal</code> the sender was given is aborted and the send is logged as <code>email.send_failed</code>, with no retry, so a mail service that hangs holds up nothing behind it. A sender function is given <code>signal</code>, as on the Node server, and may pass it to its <code>fetch</code>. On Convex the app&#39;s sender action cannot be given a signal or be cancelled, so this is a limit of the Convex adapter: the action is passed <code>deadline</code> instead, the time in milliseconds since the epoch at which Evo Auth stops waiting, from which it can set its own request timeout. On Convex the email job runs at most once, so a storage failure inside it is not retried and that one message is lost; the person asks for a new code. The message holds <code>type</code>, <code>to</code>, <code>subject</code>, <code>text</code>, <code>html</code>, and <code>code</code>, <code>url</code> and <code>expiresAt</code> when it has them: the code and the link sign someone in, so the sender must not log them. The one sender that may is <code>devConsoleSender()</code>, for local development: it sends nothing and writes each message&#39;s code and link to the auth side&#39;s log, so a first sign-up needs no mail account. <code>validateConfig</code> refuses it unless <code>cookies.devMode</code> is on, and each send refuses unless the host says the auth side is local: <code>evo-auth-server</code> once <code>listen()</code> has bound a loopback address (never a handler the app mounts and serves with only <code>start()</code>), and the Convex adapter when the deployment&#39;s <code>CONVEX_CLOUD_URL</code> is on a loopback host (a local backend), since a cloud deployment made by <code>npx convex dev</code> runs the same config with devMode on. A host says so through the optional <code>localAuthSide</code> member of <code>auth.handler</code>&#39;s and <code>auth.sendEmailChallenge</code>&#39;s context. A refused send is logged as <code>email.send_failed</code>, with no code.</li></ul><h4 id="emailtemplates" tabindex="-1"><code>email.templates</code> <a class="header-anchor" href="#emailtemplates" aria-label="Permalink to &quot;`email.templates`&quot;">​</a></h4><ul><li>Type: <code>EmailTemplates</code></li><li>Default: none (the built-in templates)</li><li>Limits: an object whose keys are message types (sign_in, sign_up, verify_address, reset_password, existing_account_notice, password_disabled, reverify, invitation), each an object of up to three functions subject, text and html, each taking the message&#39;s details and returning text</li><li>Description: Replaces parts of the built-in messages: each function given replaces the part of the same name for that type and leaves the others. Every message keeps a plain-text part (empty text falls back to the built-in text) and the code never goes in the subject (a subject holding it falls back to the built-in subject). An html function must escape what it puts in the HTML.</li></ul><h3 id="emailauth" tabindex="-1"><code>emailAuth</code> <a class="header-anchor" href="#emailauth" aria-label="Permalink to &quot;`emailAuth`&quot;">​</a></h3><h4 id="emailauthcode" tabindex="-1"><code>emailAuth.code</code> <a class="header-anchor" href="#emailauthcode" aria-label="Permalink to &quot;`emailAuth.code`&quot;">​</a></h4><ul><li>Type: <code>boolean</code></li><li>Default: <code>false</code></li><li>Limits: true or false; true needs email.sender</li><li>Description: Sign-in by a 6-digit code sent by email, typed in the browser that asked for it. The code lasts 10 minutes, works once, and 5 wrong tries void it. Signing in by an emailed code is not NIST-grade (NIST SP 800-63B-4 does not allow email for out-of-band authentication); it is offered because most sign-in products offer it and anyone with the mailbox can already reset a password. Adds <code>POST {basePath}/email/sign-in/code</code> and <code>POST {basePath}/email/verify</code>.</li></ul><h4 id="emailauthlink" tabindex="-1"><code>emailAuth.link</code> <a class="header-anchor" href="#emailauthlink" aria-label="Permalink to &quot;`emailAuth.link`&quot;">​</a></h4><ul><li>Type: <code>boolean</code></li><li>Default: <code>false</code></li><li>Limits: true or false; true needs email.sender</li><li>Description: Sign-in by a link sent by email, to the app&#39;s <code>signInUrl</code> with <code>?evo_email_link=</code> and a token. It completes only in the browser that asked for it, and only when the page&#39;s button is pressed, so a mail scanner that opens links cannot use it up. It lasts 10 minutes and works once; with <code>emailAuth.code</code> on, the same message carries both. Adds <code>POST {basePath}/email/sign-in/code</code> and <code>POST {basePath}/email/verify-link</code>.</li></ul><h4 id="emailauthsignup" tabindex="-1"><code>emailAuth.signUp</code> <a class="header-anchor" href="#emailauthsignup" aria-label="Permalink to &quot;`emailAuth.signUp`&quot;">​</a></h4><ul><li>Type: <code>boolean</code></li><li>Default: <code>false</code></li><li>Limits: true or false; true needs email.sender</li><li>Description: Whether an email code or link may make a new account. Off: only an address that already has an email account gets a message, and an unknown address gets the same answer and no email. On: the code or link for an unknown address makes the user and the email account when it is used. Either way no account exists until the address is proven, and an email account is never joined to another account because the address matches.</li></ul><h4 id="emailauthpassword" tabindex="-1"><code>emailAuth.password</code> <a class="header-anchor" href="#emailauthpassword" aria-label="Permalink to &quot;`emailAuth.password`&quot;">​</a></h4><ul><li>Type: <code>boolean</code></li><li>Default: <code>false</code></li><li>Limits: true or false; true needs email.sender and the EVO_AUTH_PASSWORD_PEPPER variable</li><li>Description: Sign-in by email address and password. Passwords are hashed with PBKDF2-HMAC-SHA256 at 600,000 iterations and a pepper, <code>EVO_AUTH_PASSWORD_PEPPER</code>, which <code>evo-auth init</code> writes, with or without <code>--server</code>; if the pepper leaks, replacing it means every user resets their password. Adds <code>POST {basePath}/email/sign-in/password</code>, the reset by email (<code>POST {basePath}/email/reset/request</code> and <code>POST {basePath}/email/reset/complete</code>), setting or changing the password of a signed-in user (<code>POST {basePath}/email/password/change</code>), adding an address to a signed-in user (<code>POST {basePath}/email/add</code> and <code>POST {basePath}/email/add/verify</code>), and, with <code>emailAuth.signUp</code> on, <code>POST {basePath}/email/sign-up</code>, which makes nothing until the emailed code is used. 10 failed sign-ins in 15 minutes stop sign-in for the address for a while, and 100 in a row turn the password off until it is reset by email.</li></ul><h3 id="password" tabindex="-1"><code>password</code> <a class="header-anchor" href="#password" aria-label="Permalink to &quot;`password`&quot;">​</a></h3><h4 id="passwordminlength" tabindex="-1"><code>password.minLength</code> <a class="header-anchor" href="#passwordminlength" aria-label="Permalink to &quot;`password.minLength`&quot;">​</a></h4><ul><li>Type: <code>integer</code></li><li>Default: <code>15</code></li><li>Limits: a whole number from 8 to 128</li><li>Description: The fewest characters a password may have, each Unicode code point counting as one; the most is 128. NIST SP 800-63B-4 asks for 15 when the password is the only factor and allows 8 when it is one of several. There are no composition rules. Applies only while <code>emailAuth.password</code> is true.</li></ul><h4 id="passwordbreachcheck" tabindex="-1"><code>password.breachCheck</code> <a class="header-anchor" href="#passwordbreachcheck" aria-label="Permalink to &quot;`password.breachCheck`&quot;">​</a></h4><ul><li>Type: <code>boolean</code></li><li>Default: <code>true</code></li><li>Limits: true or false</li><li>Description: Refuses a new password that appears in Have I Been Pwned&#39;s Pwned Passwords list. Only the first 5 hex characters of the password&#39;s SHA-1 leave the server, with padding asked for, and the service needs no account. When it cannot be reached the check is skipped and <code>password.breach_check_unavailable</code> is logged. Applies only while <code>emailAuth.password</code> is true.</li></ul><h3 id="usernames" tabindex="-1"><code>usernames</code> <a class="header-anchor" href="#usernames" aria-label="Permalink to &quot;`usernames`&quot;">​</a></h3><h4 id="usernamesenabled" tabindex="-1"><code>usernames.enabled</code> <a class="header-anchor" href="#usernamesenabled" aria-label="Permalink to &quot;`usernames.enabled`&quot;">​</a></h4><ul><li>Type: <code>boolean</code></li><li>Default: <code>false</code></li><li>Limits: true or false; true needs emailAuth.password</li><li>Description: Sign-in by username: a person with an email account may choose a username on their account page and sign in with it and their password where they would type their address. A username is a second name for the email account&#39;s password, not a new secret: 3 to 30 letters, digits, dots, dashes or underscores, lower-cased, starting and ending with a letter or digit, never all digits and never holding <code>@</code>, so one sign-in field takes either an address or a username. Adds <code>POST {basePath}/username/sign-in</code> and <code>POST {basePath}/account/username</code>, and <code>GET {basePath}/me</code> carries the name. <code>POST {basePath}/email/sign-up</code> takes an optional <code>username</code>, set when the code or link is verified if no one holds it by then; no answer before that says whether it is taken. Usernames are public: anyone willing to make accounts can learn which names are taken, and anyone who sees a username can use up that person&#39;s password to its 100-failure ceiling, which a reset by email clears. Off: both routes answer the generic 404, a sign-up that carries <code>username</code> is refused, and names already chosen stay stored and come back into force when it is turned on again. Needs <code>emailAuth.password</code>.</li></ul><h4 id="usernamesreserved" tabindex="-1"><code>usernames.reserved</code> <a class="header-anchor" href="#usernamesreserved" aria-label="Permalink to &quot;`usernames.reserved`&quot;">​</a></h4><ul><li>Type: <code>string[]</code></li><li>Default: [] (the built-in list only)</li><li>Limits: a list of at most 200 names, each passing the username rule</li><li>Description: Names no one may choose, added to the built-in list: admin, administrator, root, system, support, help, security, staff, moderator, owner, api, auth, login, signin, signup, logout, settings, account, www, mail, null and undefined. Names are compared lower-cased with dots, dashes and underscores removed, so <code>ad.min</code> is reserved too. The list applies to new choices only: a name someone already holds stays theirs.</li></ul><h3 id="secondfactor" tabindex="-1"><code>secondFactor</code> <a class="header-anchor" href="#secondfactor" aria-label="Permalink to &quot;`secondFactor`&quot;">​</a></h3><h4 id="secondfactorenabled" tabindex="-1"><code>secondFactor.enabled</code> <a class="header-anchor" href="#secondfactorenabled" aria-label="Permalink to &quot;`secondFactor.enabled`&quot;">​</a></h4><ul><li>Type: <code>boolean</code></li><li>Default: <code>false</code></li><li>Limits: true or false; true needs the EVO_AUTH_SECOND_FACTOR_KEY variable</li><li>Description: Two-step sign-in: a signed-in user may turn on a second step for themselves, a 6-digit code from an authenticator app, with ten single-use backup codes for when the app is lost. Adds <code>POST {basePath}/second-factor/totp/start</code> and <code>/second-factor/totp/confirm</code> (turn it on, or replace the authenticator), <code>/second-factor/backup-codes/regenerate</code>, <code>/second-factor/remove</code>, and, with admins listed, <code>POST {basePath}/admin/user/second-factor/remove</code> for a person who has lost both. At sign-in, a user who has one gets no session from the first factor: it answers the pending step (JSON routes answer <code>secondFactor</code>; a provider&#39;s callback goes to <code>signInUrl</code> with <code>?evo_step=second_factor</code>) and <code>GET {basePath}/signin/second-factor</code>, <code>POST {basePath}/signin/second-factor/verify</code> (an authenticator code, a backup code or, with <code>passkeys.enabled</code>, a passkey) and <code>POST {basePath}/signin/second-factor/cancel</code> complete or end it within 10 minutes and 5 wrong attempts. A passkey sign-in is never asked for a second step. Each change needs a recent confirmation of identity, and a notice email goes to the user&#39;s email account when <code>email.sender</code> is set. The secrets are sealed under <code>EVO_AUTH_SECOND_FACTOR_KEY</code>. Off: the routes answer the generic 404 and a second factor already set up is not asked for; <code>evo-auth-server check</code> warns while users still have one.</li></ul><h4 id="secondfactorrequired" tabindex="-1"><code>secondFactor.required</code> <a class="header-anchor" href="#secondfactorrequired" aria-label="Permalink to &quot;`secondFactor.required`&quot;">​</a></h4><ul><li>Type: <code>boolean</code></li><li>Default: <code>false</code></li><li>Limits: true or false; true needs secondFactor.enabled</li><li>Description: Every user must have a second factor: one who has none is taken through setting up an authenticator during sign-in, before they get a session; a passkey also counts. A user may still turn their own second factor off, and is then taken through set-up at their next sign-in. NIST SP 800-63B-4 allows <code>password.minLength</code> 8 only when a second factor is required; the minimum does not change by itself.</li></ul><h3 id="providers" tabindex="-1"><code>providers</code> <a class="header-anchor" href="#providers" aria-label="Permalink to &quot;`providers`&quot;">​</a></h3><ul><li>Type: <code>Provider[]</code></li><li>Default: none; the setting is required</li><li>Limits: a list of plain provider objects whose own data members are a unique id (a lower-case letter, then 1 to 31 lower-case letters or digits), kind oauth2 or oidc, a label (non-empty text with no control character), the functions authorizationUrl, exchangeCode and fetchProfile, and optionally endpoints, a list of absolute https URLs with no user name, password, query or fragment (http on a loopback host needs cookies.devMode), and icon, { light, dark?, shape? }, light and dark each a data:image/svg+xml or data:image/png URI of at most 8192 characters and shape mark, square or full</li><li>Description: The enabled sign-in providers, for example <code>[github()]</code>, or a provider object the app writes itself. Each provider&#39;s client id and secret are the variables <code>EVO_AUTH_{ID}_CLIENT_ID</code> and <code>EVO_AUTH_{ID}_CLIENT_SECRET</code>, with its id in upper case.</li></ul><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h2><p>Every variable appears once, in the order the definition lists it.</p><h3 id="evo_auth_secret" tabindex="-1"><code>EVO_AUTH_SECRET</code> <a class="header-anchor" href="#evo_auth_secret" aria-label="Permalink to &quot;`EVO_AUTH_SECRET`&quot;">​</a></h3><ul><li>Read by: <code>auth</code> (required)</li><li>Holds a secret: yes</li><li>Purpose: The master secret. Its decoded bytes are the HKDF input for every internal key: the client-address HMAC key, the sign-in cookie key and the refresh MAC key.</li><li>Strength rule: base64url text without padding that decodes to at least 32 bytes; generate 32 random bytes</li></ul><h3 id="evo_auth_proxy_secret" tabindex="-1"><code>EVO_AUTH_PROXY_SECRET</code> <a class="header-anchor" href="#evo_auth_proxy_secret" aria-label="Permalink to &quot;`EVO_AUTH_PROXY_SECRET`&quot;">​</a></h3><ul><li>Read by: <code>proxy</code> (required), <code>auth</code> (not required)</li><li>Holds a secret: yes</li><li>Purpose: Shared by the auth deployment and the app&#39;s proxy only. When set on the auth side, every request must carry it in <code>X-Evo-Proxy-Secret</code> and the client address is read only from <code>X-Evo-Client-IP</code>. The proxy role requires it. The auth role reads it when it is set and does not refuse to start without it, but on Convex, outside the development cookie mode, every auth route answers unavailable until it is set.</li><li>Strength rule: base64url text without padding that decodes to at least 32 bytes, the rule of EVO_AUTH_SECRET, and it must differ from EVO_AUTH_SECRET; fromEnv refuses it otherwise</li></ul><h3 id="evo_auth_password_pepper" tabindex="-1"><code>EVO_AUTH_PASSWORD_PEPPER</code> <a class="header-anchor" href="#evo_auth_password_pepper" aria-label="Permalink to &quot;`EVO_AUTH_PASSWORD_PEPPER`&quot;">​</a></h3><ul><li>Read by: <code>auth</code> (not required)</li><li>Holds a secret: yes</li><li>Purpose: The pepper of every password hash: an HMAC-SHA256 over the PBKDF2 output is keyed by it, so a copy of the database alone cannot be used to guess passwords. Required while <code>emailAuth.password</code> is true; createAuth refuses to start without it. It is its own variable, not derived from EVO_AUTH_SECRET, which can be replaced. If it leaks, replacing it means every user resets their password.</li><li>Strength rule: base64url text without padding that decodes to at least 32 bytes, the rule of EVO_AUTH_SECRET, and it must differ from EVO_AUTH_SECRET; generate 32 random bytes</li></ul><h3 id="evo_auth_second_factor_key" tabindex="-1"><code>EVO_AUTH_SECOND_FACTOR_KEY</code> <a class="header-anchor" href="#evo_auth_second_factor_key" aria-label="Permalink to &quot;`EVO_AUTH_SECOND_FACTOR_KEY`&quot;">​</a></h3><ul><li>Read by: <code>auth</code> (not required)</li><li>Holds a secret: yes</li><li>Purpose: The key every authenticator secret and every backup code is sealed under, through an HKDF label of its own. Required while <code>secondFactor.enabled</code> is true; createAuth refuses to start without it, and with the setting off nothing reads it. It is its own variable, not derived from EVO_AUTH_SECRET, so replacing the master secret does not lock anyone out. To replace this key without locking anyone out, set EVO_AUTH_SECOND_FACTOR_KEY_PREVIOUS to its old value first and run the reseal (docs/rotating-secrets.md).</li><li>Strength rule: base64url text without padding that decodes to at least 32 bytes, the rule of EVO_AUTH_SECRET, and it must differ from EVO_AUTH_SECRET and from EVO_AUTH_PASSWORD_PEPPER; generate 32 random bytes</li></ul><h3 id="evo_auth_second_factor_key_previous" tabindex="-1"><code>EVO_AUTH_SECOND_FACTOR_KEY_PREVIOUS</code> <a class="header-anchor" href="#evo_auth_second_factor_key_previous" aria-label="Permalink to &quot;`EVO_AUTH_SECOND_FACTOR_KEY_PREVIOUS`&quot;">​</a></h3><ul><li>Read by: <code>auth</code> (not required)</li><li>Holds a secret: yes</li><li>Purpose: The second-factor key being replaced, set only while the key is rotated: authenticator secrets and backup codes sealed under it still open, each successful use moves that user&#39;s values to EVO_AUTH_SECOND_FACTOR_KEY, and the reseal moves the rest. Read only while <code>secondFactor.enabled</code> is true, and by the reseal whatever the setting. Remove it once the reseal reports 0 and 0; <code>evo-auth check</code> and <code>evo-auth-server check</code> warn while it is set.</li><li>Strength rule: the rule of EVO_AUTH_SECOND_FACTOR_KEY: base64url text without padding that decodes to at least 32 bytes, different from EVO_AUTH_SECRET and from EVO_AUTH_PASSWORD_PEPPER; it may equal EVO_AUTH_SECOND_FACTOR_KEY while the rotation starts</li></ul><h3 id="evo_auth_signing_key" tabindex="-1"><code>EVO_AUTH_SIGNING_KEY</code> <a class="header-anchor" href="#evo_auth_signing_key" aria-label="Permalink to &quot;`EVO_AUTH_SIGNING_KEY`&quot;">​</a></h3><ul><li>Read by: <code>auth</code> (required)</li><li>Holds a secret: yes</li><li>Purpose: The active private signing key for access tokens. Its <code>kid</code> is recomputed as the RFC 7638 thumbprint.</li><li>Strength rule: an ES256 (P-256) private key as a JWK whose public part is in EVO_AUTH_PUBLIC_KEYS</li></ul><h3 id="evo_auth_staged_signing_key" tabindex="-1"><code>EVO_AUTH_STAGED_SIGNING_KEY</code> <a class="header-anchor" href="#evo_auth_staged_signing_key" aria-label="Permalink to &quot;`EVO_AUTH_STAGED_SIGNING_KEY`&quot;">​</a></h3><ul><li>Read by: no role</li><li>Holds a secret: yes</li><li>Purpose: The private key <code>evo-auth keys rotate</code> stages, until <code>evo-auth keys activate &lt;kid&gt;</code> makes it <code>EVO_AUTH_SIGNING_KEY</code>. After activation it holds the previous signing key, so the printed rollback command works until that key&#39;s <code>removeAfter</code>. No library role reads it, and it is never sent to a deployment.</li><li>Strength rule: none stated</li><li>Note: the command line writes this variable; it does not go in <code>.env.example</code>.</li></ul><h3 id="evo_auth_public_keys" tabindex="-1"><code>EVO_AUTH_PUBLIC_KEYS</code> <a class="header-anchor" href="#evo_auth_public_keys" aria-label="Permalink to &quot;`EVO_AUTH_PUBLIC_KEYS`&quot;">​</a></h3><ul><li>Read by: <code>render</code> (required), <code>auth</code> (required)</li><li>Holds a secret: no</li><li>Purpose: The public key set: the active key plus any retiring ones, each retiring key with a removeAfter time. Published at <code>{publicUrl}/.well-known/jwks.json</code>.</li><li>Strength rule: a JSON list of ES256 (P-256) public JWKs that contains the active key</li></ul><h3 id="evo_auth_id_client_id" tabindex="-1"><code>EVO_AUTH_{ID}_CLIENT_ID</code> <a class="header-anchor" href="#evo_auth_id_client_id" aria-label="Permalink to &quot;`EVO_AUTH_{ID}_CLIENT_ID`&quot;">​</a></h3><ul><li>Read by: <code>auth</code> (required); read only when the <code>{id}</code> provider is enabled</li><li>Holds a secret: no</li><li>Purpose: The client id of the OAuth app registered with one provider. <code>{ID}</code> is the provider&#39;s id in upper case, so <code>github()</code> reads <code>EVO_AUTH_GITHUB_CLIENT_ID</code> and a provider with id <code>acme</code> reads <code>EVO_AUTH_ACME_CLIENT_ID</code>. Required for each provider in <code>providers</code>, read only for those.</li><li>Strength rule: none stated</li></ul><h3 id="evo_auth_id_client_secret" tabindex="-1"><code>EVO_AUTH_{ID}_CLIENT_SECRET</code> <a class="header-anchor" href="#evo_auth_id_client_secret" aria-label="Permalink to &quot;`EVO_AUTH_{ID}_CLIENT_SECRET`&quot;">​</a></h3><ul><li>Read by: <code>auth</code> (required); read only when the <code>{id}</code> provider is enabled</li><li>Holds a secret: yes</li><li>Purpose: The client secret of the OAuth app registered with one provider. <code>{ID}</code> is the provider&#39;s id in upper case, so <code>github()</code> reads <code>EVO_AUTH_GITHUB_CLIENT_SECRET</code> and a provider with id <code>acme</code> reads <code>EVO_AUTH_ACME_CLIENT_SECRET</code>. Required for each provider in <code>providers</code>, read only for those.</li><li>Strength rule: none stated</li></ul>',208)])])}const p=i(s,[["render",n]]);export{m as __pageData,p as default};
